css:
.yin-yang-loader {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 200px;
}
.yin-yang {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(90deg, white 50%, black 50%);
  animation: rotate 4s linear infinite;
  position: relative;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.15);
}
.yin-yang::before,
.yin-yang::after {
  content: "";
  position: absolute;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  left: 50%;
  transform: translateX(-50%);
}
.yin-yang::before {
  top: 0;
  background: black;
}
.yin-yang::after {
  bottom: 0;
  background: white;
}
.dot {
  position: absolute;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1;
}
.dot.white {
  background: white;
  top: 30px;
}
.dot.black {
  background: black;
  bottom: 30px;
}
@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.yin-yang {
  transition: box-shadow 0.3s ease;
}

.yin-yang:hover {
  box-shadow: 0 0 30px rgba(0, 0, 0, 0.2);
}
@keyframes pulse {
  0%,
  100% {
    transform: translateX(-50%) scale(1);
  }
  50% {
    transform: translateX(-50%) scale(1.1);
  }
}
.dot {
  animation: pulse 4s ease-in-out infinite;
}
